package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"os"

	"case_runner/db"
)

const schema = `CREATE TABLE events (
    id INTEGER PRIMARY KEY,
    created_at INTEGER NOT NULL,
    julian REAL NOT NULL,
    label TEXT NOT NULL,
    flag INTEGER NOT NULL
);
`

const seed = `INSERT INTO events (id, created_at, julian, label, flag) VALUES (1, 1700000000, 2460000.5, '2024-02-29', 1), (2, 0, 2440587.5, 'not a date', 0), (3, 86400, 2451545.0, '2000-01-01 12:00:00', 2)`

type results map[string]any

func (r results) record(name string, read func() (any, error)) {
	value, err := read()
	if err != nil {
		r[name] = "error: " + err.Error()
		return
	}
	r[name] = value
}

func main() {
	conn, err := sql.Open(databaseDriver, ":memory:")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer conn.Close()
	conn.SetMaxOpenConns(1)

	ctx := context.Background()
	for _, statement := range []string{schema, seed} {
		if _, err := conn.ExecContext(ctx, statement); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}

	queries := db.New(conn)
	output := results{}
	output.record("days", func() (any, error) { return queries.Days(ctx) })
	output.record("flags", func() (any, error) { return queries.Flags(ctx) })

	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(output); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
